// Two `Expression(...)` heads with one key are one call; `.Pin[i] = x` lines are its pin arguments.
/// @name M_LpExpressionBlock
export void M_LpExpressionBlock(inout material Base)
{
    float PhaseG = 0;
    float PhaseG2 = 0;
    PhaseG = 0.5;
    PhaseG2 = 0.25;
    UE.Expression(Class = "VolumetricAdvancedMaterialOutput", bGroundContribution = "false", Pin[0] = PhaseG, Pin[1] = PhaseG2);
}
